<?php
namespace App\Http\Controllers;
use App\Models\{Listing,ListingVersion,Marketplace,Product}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ListingController extends Controller {
 public function index(Request $r){$listings=Listing::with(['product','marketplace'])->when($r->q,fn($q,$s)=>$q->where('title','like',"%$s%"))->when($r->marketplace_id,fn($q,$v)=>$q->where('marketplace_id',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(20)->withQueryString();return view('listings.index',['listings'=>$listings,'marketplaces'=>Marketplace::active()->orderBy('name')->get()]);}
 public function create(){return view('listings.form',['listing'=>new Listing(['status'=>'draft']),'products'=>Product::orderBy('name')->get(),'marketplaces'=>Marketplace::active()->orderBy('name')->get()]);}
 public function store(Request $r){$data=$this->validated($r);$listing=DB::transaction(function()use($data){$l=Listing::create($data);$this->score($l);$this->snapshot($l);return $l;});return redirect()->route('listings.show',$listing)->with('success','Listing created and scored.');}
 public function show(Listing $listing){$listing->load(['product','marketplace','versions.user']);return view('listings.show',compact('listing'));}
 public function edit(Listing $listing){return view('listings.form',['listing'=>$listing,'products'=>Product::orderBy('name')->get(),'marketplaces'=>Marketplace::active()->orderBy('name')->get()]);}
 public function update(Request $r,Listing $listing){$data=$this->validated($r);DB::transaction(function()use($listing,$data){$listing->update($data);$this->score($listing);$this->snapshot($listing);});return redirect()->route('listings.show',$listing)->with('success','Listing updated; a version snapshot was saved.');}
 private function validated(Request $r):array{return $r->validate(['product_id'=>'required|exists:products,id','marketplace_id'=>'required|exists:marketplaces,id','external_listing_id'=>'nullable|string|max:120','title'=>'required|string|max:500','bullet_points'=>'nullable|array|max:10','bullet_points.*'=>'nullable|string|max:1000','description'=>'nullable|string|max:20000','backend_keywords'=>'nullable|string|max:5000','special_features'=>'nullable|array','special_features.*'=>'string|max:255','has_a_plus_content'=>'nullable|boolean','image_urls'=>'nullable|array|max:20','image_urls.*'=>'url|max:2000','status'=>'required|in:draft,active,suppressed,inactive']);}
 private function score(Listing $l):void{$result=$l->calculateScore();$l->update(['score'=>$result['score'],'score_breakdown'=>$result['breakdown']]);}
 private function snapshot(Listing $l):void{$version=(int)$l->versions()->max('version')+1;$l->versions()->create(['version'=>$version,'snapshot'=>$l->only(['product_id','marketplace_id','external_listing_id','title','bullet_points','description','backend_keywords','special_features','has_a_plus_content','image_urls','status','score','score_breakdown']),'created_by'=>auth()->id()]);}
}
